import{_ as a,o as l,c as i,ae as o}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"UI and UX Plan","description":"","frontmatter":{},"headers":[],"relativePath":"sessions/20260226-helios-market-research/11_UI_UX_PLAN.md","filePath":"sessions/20260226-helios-market-research/11_UI_UX_PLAN.md"}'),r={name:"sessions/20260226-helios-market-research/11_UI_UX_PLAN.md"};function t(s,e,n,c,d,u){return l(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="ui-and-ux-plan" tabindex="-1">UI and UX Plan <a class="header-anchor" href="#ui-and-ux-plan" aria-label="Permalink to &quot;UI and UX Plan&quot;">​</a></h1><p>Date: 2026-02-26</p><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Design a rich, high-density UX on top of a terminal-first architecture without compromising responsiveness.</p><h2 id="research-input-co-lab" tabindex="-1">Research Input: Co(lab) <a class="header-anchor" href="#research-input-co-lab" aria-label="Permalink to &quot;Research Input: Co(lab)&quot;">​</a></h2><p>Reference reviewed: <code>blackboardsh/colab</code>.</p><p>Observed product signals:</p><ul><li>hybrid browser + code/editor workspace</li><li>multi-tab and multi-pane work model</li><li>plugin architecture emphasis</li><li>startup-builder workflow orientation</li><li>ElectroBun-based shell</li></ul><p>Implication for Helios:</p><ul><li>rich UX is feasible on ElectroBun</li><li>density and workflow composability can coexist with low-overhead goals if rendering and event paths stay bounded</li></ul><h2 id="ux-positioning-for-helios" tabindex="-1">UX Positioning for Helios <a class="header-anchor" href="#ux-positioning-for-helios" aria-label="Permalink to &quot;UX Positioning for Helios&quot;">​</a></h2><p>Helios should be a:</p><ul><li>terminal-native control center with rich orchestration UX</li><li>not a traditional IDE clone</li></ul><p>Primary UX promise:</p><ul><li>high-speed terminal execution plus first-class visibility/control for worktrees, agent lanes, approvals, and handoffs</li></ul><h2 id="information-architecture" tabindex="-1">Information Architecture <a class="header-anchor" href="#information-architecture" aria-label="Permalink to &quot;Information Architecture&quot;">​</a></h2><h3 id="global-shell" tabindex="-1">Global shell <a class="header-anchor" href="#global-shell" aria-label="Permalink to &quot;Global shell&quot;">​</a></h3><ul><li><p>Top bar:</p><ul><li>workspace/project switcher</li><li>global command palette</li><li>provider profile indicator</li><li>renderer indicator (<code>ghostty</code>/<code>rio</code>)</li><li>system health and policy state</li></ul></li><li><p>Left rail:</p><ul><li>Workspaces</li><li>Worktree lanes (<code>par</code>)</li><li>Sessions (<code>zellij</code> namespaces)</li><li>Shared sessions (<code>upterm</code>/<code>tmate</code>)</li><li>Audit timeline</li></ul></li><li><p>Main stage:</p><ul><li>tabbed/split terminal canvas</li><li>lane-aware terminal grouping</li></ul></li><li><p>Right rail (context panel):</p><ul><li>lane metadata</li><li>approvals queue</li><li>diff/review panel</li><li>run logs and metrics</li></ul></li></ul><h3 id="modal-overlays" tabindex="-1">Modal overlays <a class="header-anchor" href="#modal-overlays" aria-label="Permalink to &quot;Modal overlays&quot;">​</a></h3><ul><li>Renderer switch modal (hot swap or restart flow)</li><li>Share session modal (<code>upterm</code>/<code>tmate</code> controls + TTL)</li><li>Policy decision modal for sensitive actions</li></ul><h2 id="core-user-flows" tabindex="-1">Core User Flows <a class="header-anchor" href="#core-user-flows" aria-label="Permalink to &quot;Core User Flows&quot;">​</a></h2><h3 id="flow-1-new-task-lane" tabindex="-1">Flow 1: New task lane <a class="header-anchor" href="#flow-1-new-task-lane" aria-label="Permalink to &quot;Flow 1: New task lane&quot;">​</a></h3><ol><li>User clicks <code>+ Task Lane</code>.</li><li>Select repo, branch strategy, provider profile.</li><li>Helios creates worktree via <code>par</code>.</li><li>Creates/attaches zellij session and terminals.</li><li>Lane appears in left rail with live status.</li></ol><h3 id="flow-2-renderer-switch" tabindex="-1">Flow 2: Renderer switch <a class="header-anchor" href="#flow-2-renderer-switch" aria-label="Permalink to &quot;Flow 2: Renderer switch&quot;">​</a></h3><ol><li>User toggles renderer in settings.</li><li>Helios runs capability check.</li><li>If hot swap supported, switch in-place with brief output pause.</li><li>If not supported, show fast restart confirmation and preserve session state via zmx.</li></ol><h3 id="flow-3-human-handoff" tabindex="-1">Flow 3: Human handoff <a class="header-anchor" href="#flow-3-human-handoff" aria-label="Permalink to &quot;Flow 3: Human handoff&quot;">​</a></h3><ol><li>Operator selects terminal and clicks <code>Share</code>.</li><li>Chooses <code>upterm</code> or <code>tmate</code>.</li><li>Approval gate checks policy.</li><li>Share link/command generated with TTL and permissions.</li><li>Audit event recorded and visible in timeline.</li></ol><h3 id="flow-4-approval-and-apply" tabindex="-1">Flow 4: Approval and apply <a class="header-anchor" href="#flow-4-approval-and-apply" aria-label="Permalink to &quot;Flow 4: Approval and apply&quot;">​</a></h3><ol><li>Agent proposes command/edit.</li><li>UI shows rationale + impact + diff.</li><li>User approves/denies.</li><li>Result streams back into lane timeline and audit log.</li></ol><h2 id="ui-components" tabindex="-1">UI Components <a class="header-anchor" href="#ui-components" aria-label="Permalink to &quot;UI Components&quot;">​</a></h2><h3 id="must-have-components" tabindex="-1">Must-have components <a class="header-anchor" href="#must-have-components" aria-label="Permalink to &quot;Must-have components&quot;">​</a></h3><ul><li>Lane list with health states: <code>idle</code>, <code>running</code>, <code>blocked</code>, <code>error</code>, <code>shared</code></li><li>Terminal card with provider/session badges</li><li>Approval queue panel with policy reason text</li><li>Diff drawer with staged apply/rollback controls</li><li>Share session drawer with revoke button and expiry timer</li><li>Event timeline with filter chips (<code>terminal</code>, <code>agent</code>, <code>policy</code>, <code>share</code>, <code>audit</code>)</li></ul><h3 id="richness-without-bloat" tabindex="-1">Richness without bloat <a class="header-anchor" href="#richness-without-bloat" aria-label="Permalink to &quot;Richness without bloat&quot;">​</a></h3><ul><li>Prefer progressive disclosure: <ul><li>lightweight default view</li><li>deep details in drawers/panels</li></ul></li><li>Keep heavy charts optional and lazily mounted</li></ul><h2 id="interaction-model" tabindex="-1">Interaction Model <a class="header-anchor" href="#interaction-model" aria-label="Permalink to &quot;Interaction Model&quot;">​</a></h2><ul><li><p>Keyboard-first operations:</p><ul><li>lane navigation</li><li>split/tab actions</li><li>share/revoke</li><li>approve/deny</li></ul></li><li><p>Mouse interactions are secondary but fully supported.</p></li><li><p>Real-time updates:</p><ul><li>driven from internal local bus events</li><li>AG-UI mapping used for frontend stream abstraction</li></ul></li></ul><h2 id="visual-system" tabindex="-1">Visual System <a class="header-anchor" href="#visual-system" aria-label="Permalink to &quot;Visual System&quot;">​</a></h2><ul><li><p>Terminal-first visual hierarchy:</p><ul><li>dark neutral base, strong semantic status colors</li><li>high contrast for state-critical chips and warnings</li></ul></li><li><p>Typography:</p><ul><li>monospace for terminal and command/diff surfaces</li><li>sans for navigation and metadata</li></ul></li><li><p>Motion:</p><ul><li>small, purposeful transitions for lane state and modal operations</li><li>no continuous decorative animation</li></ul></li></ul><h2 id="performance-ux-rules" tabindex="-1">Performance UX Rules <a class="header-anchor" href="#performance-ux-rules" aria-label="Permalink to &quot;Performance UX Rules&quot;">​</a></h2><ul><li>Do not re-render inactive terminal panes.</li><li>Throttle high-frequency output paint updates.</li><li>Keep event timeline virtualized.</li><li>Show explicit backpressure indicator when output bursts are clipped.</li></ul><h2 id="safety-ux-rules" tabindex="-1">Safety UX Rules <a class="header-anchor" href="#safety-ux-rules" aria-label="Permalink to &quot;Safety UX Rules&quot;">​</a></h2><ul><li>Destructive or share actions always require explicit confirmation.</li><li>Show policy reason and violated rule for denied actions.</li><li>Make revoke/rollback controls always one interaction away.</li></ul><h2 id="configuration-ux" tabindex="-1">Configuration UX <a class="header-anchor" href="#configuration-ux" aria-label="Permalink to &quot;Configuration UX&quot;">​</a></h2><p>Settings sections:</p><ul><li>Renderer (<code>ghostty</code>/<code>rio</code> + hot swap preference)</li><li>Session (<code>zellij</code>, zmx checkpoint cadence)</li><li>Collaboration (<code>upterm</code>/<code>tmate</code> defaults, TTL, allowlist)</li><li>Protocol (<code>ACP</code>, MCP, A2A adapter toggles)</li><li>Policy (command/path rules)</li></ul><h2 id="mvp-surface" tabindex="-1">MVP Surface <a class="header-anchor" href="#mvp-surface" aria-label="Permalink to &quot;MVP Surface&quot;">​</a></h2><p>Must ship in MVP:</p><ul><li>Worktree lane manager</li><li>terminal mux canvas</li><li>approvals queue</li><li>share session controls</li><li>renderer switch control</li><li>audit timeline</li></ul><p>Can defer post-MVP:</p><ul><li>highly customizable themes/layout presets</li><li>advanced plugin marketplace UI</li><li>multi-user presence indicators beyond share sessions</li></ul><h2 id="validation-plan" tabindex="-1">Validation Plan <a class="header-anchor" href="#validation-plan" aria-label="Permalink to &quot;Validation Plan&quot;">​</a></h2><ul><li>usability tests with 3 persona groups: <ul><li>terminal-heavy backend engineers</li><li>platform/on-call operators</li><li>team leads focused on governance</li></ul></li><li>benchmark task set: <ul><li>create lane, run task, share handoff, switch renderer, approve patch, rollback</li></ul></li><li>success condition: <ul><li>all benchmark tasks completed without leaving Helios UI</li></ul></li></ul><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><ul><li><code>blackboardsh/colab</code> repository and README product architecture notes: <ul><li><a href="https://github.com/blackboardsh/colab" target="_blank" rel="noreferrer">https://github.com/blackboardsh/colab</a></li></ul></li></ul>',54)])])}const m=a(r,[["render",t]]);export{p as __pageData,m as default};
